99: def format_driver_name(raw_name: str) -> str:
100:     """Convert raw feature or driver code into a clear English domain label."""
101:     clean = raw_name.strip()
102:     # Strip optional trailing parenthetical SHAP score if present, e.g. "spot_price(+12.4)"
103:     base_key = clean.split("(")[0].strip()
104:     suffix = ""
105:     if "(" in clean and clean.endswith(")"):
106:         suffix = " (" + clean.split("(", 1)[1]
107:     if base_key in FRIENDLY_DRIVER_NAMES:
108:         return FRIENDLY_DRIVER_NAMES[base_key] + suffix
109:     underscored = base_key.replace(" ", "_").lower()
110:     if underscored in FRIENDLY_DRIVER_NAMES:
111:         return FRIENDLY_DRIVER_NAMES[underscored] + suffix
112:     return base_key.replace("_", " ").title() + suffix
